const body = $json.body ?? $json;
const nome = String(body.nome ?? '').trim();
const email = String(body.email ?? '').trim().toLowerCase();
const telefone = String(body.telefone ?? '').trim();
const mensagem = String(body.mensagem ?? '').trim();
const origem = String(body.origem ?? 'webhook').trim();

if (!nome || !email) {
  return [{
    json: {
      sucesso: false,
      statusCode: 400,
      erro: 'Os campos nome e email são obrigatórios.'
    }
  }];
}

const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
if (!emailValido) {
  return [{
    json: {
      sucesso: false,
      statusCode: 400,
      erro: 'Informe um email válido.'
    }
  }];
}

const texto = mensagem.toLowerCase();
const termosAltoInteresse = ['orçamento', 'proposta', 'contratar', 'preço', 'reunião'];
const interesse = termosAltoInteresse.some((termo) => texto.includes(termo))
  ? 'alto'
  : mensagem.length >= 40
    ? 'médio'
    : 'baixo';

return [{
  json: {
    sucesso: true,
    statusCode: 201,
    lead: {
      nome,
      email,
      telefone,
      mensagem,
      origem,
      interesse,
      recebidoEm: new Date().toISOString()
    }
  }
}];
